// ============================================
// PROSES IMPORT
// ============================================

$success = 0;
$failed = 0;
$skipped = 0;

// Nonaktifkan foreign key
query("SET FOREIGN_KEY_CHECKS = 0");

echo "<table border='1' cellpadding='3' style='border-collapse:collapse; font-size:10px;'>";
echo "<tr style='background:#667eea; color:white;'>";
echo "<th>No</th><th>Nama Sekolah</th><th>NPSN</th><th>Bentuk</th><th>Status</th>";
echo "</tr>";

$no = 0;
foreach ($sekolah_data as $data) {
    $no++;
    list($nama_sekolah, $npsn, $bentuk, $status_sekolah, $alamat, $desa, $kecamatan, $kepsek, $nip) = $data;
    
    // Cek sudah ada
    $cek = fetchOne("SELECT id FROM sekolah WHERE npsn = '$npsn'");
    if ($cek) {
        $skipped++;
        echo "<tr><td>$no</td><td>$nama_sekolah</td><td>$npsn</td><td>$bentuk</td><td style='color:orange;'>⏭️ Skip</td></tr>";
        continue;
    }
    
    // Buat user kepala sekolah
    $kepsek_id = null;
    if (!empty($kepsek)) {
        $user = fetchOne("SELECT id FROM users WHERE name = '" . mysqli_real_escape_string($conn, $kepsek) . "' AND role = 'kepala_sekolah'");
        if (!$user) {
            $email = strtolower(preg_replace('/[^a-zA-Z0-9]/', '.', trim($kepsek))) . '@sekolah.com';
            $email = preg_replace('/\.+/', '.', $email);
            
            $sql_user = "INSERT INTO users (name, email, password, role, sekolah, nip, is_active) VALUES (
                '" . mysqli_real_escape_string($conn, $kepsek) . "',
                '" . mysqli_real_escape_string($conn, $email) . "',
                '$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2.uheWG/igi',
                'kepala_sekolah',
                '" . mysqli_real_escape_string($conn, $nama_sekolah) . "',
                " . (!empty($nip) ? "'$nip'" : "NULL") . ",
                1
            )";
            if (query($sql_user)) {
                $kepsek_id = lastId();
            }
        } else {
            $kepsek_id = $user['id'];
        }
    }
    
    // Cari pengawas
    $pengawas_id = null;
    if (!empty($kecamatan)) {
        $pengawas = fetchOne("SELECT id FROM users WHERE role = 'pengawas' AND sekolah LIKE '%" . mysqli_real_escape_string($conn, $kecamatan) . "%'");
        if ($pengawas) {
            $pengawas_id = $pengawas['id'];
        }
    }
    
    // Insert sekolah
    $sql = "INSERT INTO sekolah (
        nama_sekolah, npsn, alamat, kelurahan, kecamatan, 
        kabupaten, provinsi, kepala_sekolah, pengawas
    ) VALUES (
        '" . mysqli_real_escape_string($conn, $nama_sekolah) . "',
        '" . mysqli_real_escape_string($conn, $npsn) . "',
        '" . mysqli_real_escape_string($conn, $alamat) . "',
        '" . mysqli_real_escape_string($conn, $desa) . "',
        '" . mysqli_real_escape_string($conn, $kecamatan) . "',
        'Kabupaten Ende',
        'Nusa Tenggara Timur',
        " . ($kepsek_id ? $kepsek_id : 'NULL') . ",
        " . ($pengawas_id ? $pengawas_id : 'NULL') . "
    )";
    
    if (query($sql)) {
        $success++;
        echo "<tr><td>$no</td><td>$nama_sekolah</td><td>$npsn</td><td>$bentuk</td><td style='color:green;'>✅ Berhasil</td></tr>";
    } else {
        $failed++;
        echo "<tr><td>$no</td><td>$nama_sekolah</td><td>$npsn</td><td>$bentuk</td><td style='color:red;'>❌ Gagal</td></tr>";
    }
}

// Aktifkan foreign key
query("SET FOREIGN_KEY_CHECKS = 1");

echo "</table>";

echo "<br><br>";
echo "============================================<br>";
echo "✅ Total berhasil: <strong>$success</strong><br>";
echo "❌ Total gagal: <strong>$failed</strong><br>";
echo "⏭️ Total skip (sudah ada): <strong>$skipped</strong><br>";
echo "📊 Total data diproses: <strong>" . ($success + $failed + $skipped) . "</strong><br>";
echo "============================================<br>";

if ($success > 0) {
    echo "<br><a href='index.php' style='background:#28a745; color:white; padding:10px 20px; text-decoration:none; border-radius:5px;'>🏠 Kembali ke Beranda</a>";
